/**  A "Keep this one" action of the Problems view, for undo. */
export type ResolutionId = number;

/**  A `<font>` argument to look up (E26.1): a face id or a name. */
export type ResolveFontRequest = {
	/**
	 *  A face id (`42`) or a name: a PostScript name, a full name, or a
	 *  family with or without its style.
	 */
	font: string,
};

/**  Resolves one sidecar conflict. */
export type ResolveSidecarConflictRequest = {
	/**  The conflict. */
	id: SidecarConflictId,
	/**  The value to keep. */
	keep: ConflictSide,
};

/**  Makes an earlier version current again. */
export type RestoreLayoutRequest = {
	/**  The template file's id. */
	id: string,
	/**  The [`LayoutVersion::number`] to restore. */
	number: number,
};

/**  Goes back to the saved file, or a preset back to its shipped original. */
export type RevertLayoutRequest = {
	/**  The template file's id. */
	id: string,
	/**
	 *  Writes the shipped original of the layout's preset (the content it
	 *  replaces is kept as a version); false only reads the saved file.
	 */
	toOriginal?: boolean,
};

/**  One rule of a [`RuleGroup`]. */
export type Rule = 
/**
 *  A face passes when it passes these filters, as search applies them.
 *  `collection` may name another smart collection: its rule applies
 *  (a rule that reaches its own collection is `InvalidRequest`).
 */
{ kind: "filters"; 
/**  The filters. */
filters: Filters } | 
/**  A nested group. */
{ kind: "group"; 
/**  The group. */
group: RuleGroup };

/**
 *  A smart collection's rule: a group of rules combined with AND or OR. A
 *  group with no rules passes every face.
 */
export type RuleGroup = {
	/**  AND or OR. */
	op: RuleOp,
	/**  The rules. */
	rules?: Rule[],
};

/**  How a [`RuleGroup`] combines its rules. */
export type RuleOp = 
/**  A face must pass every rule. */
"and" | 
/**  A face must pass at least one rule. */
"or";

/**  Why a face previews other text than the sample. */
export type SampleFallback = 
/**  Letters of a script the face covers. */
{ kind: "script"; 
/**  ISO 15924 script (`Cyrl`). */
script: string } | 
/**  Characters the face maps, for a face that covers no language. */
{ kind: "symbols" };

/**  The text one face previews. */
export type SampleText = {
	/**  The face. */
	face: FaceId,
	/**  The sample text, or text from the face's own coverage. */
	text: string,
	/**  Set when the face lacks characters of the sample and `text` is other text. */
	fallback?: SampleFallback | null,
	/**  The characters of the sample the face lacks. */
	missing?: string[],
};

/**  The text to preview some faces with, for one sample text. */
export type SampleTextRequest = {
	/**  The faces. */
	faces: FaceId[],
	/**  The sample text the user chose. */
	text: string,
};

/**  Saves a comparison: a new one, or over an existing one. */
export type SaveComparisonRequest = {
	/**  The comparison to overwrite; none saves a new one. */
	id?: ComparisonId | null,
	/**  Its name; must not be empty (spaces around it are dropped). */
	name: string,
	/**  2–4 distinct faces, in the order the sheet shows them. */
	faces: FaceId[],
	/**  The mode. */
	mode?: CompareMode,
	/**  The sample text; empty means each face shows its own name. */
	sampleText?: string,
};

/**  Writes a layout to its template file; the previous content is kept as a version. */
export type SaveLayoutRequest = {
	/**  The template file's id; a new id makes a new file. */
	id: string,
	/**  The layout; its values are clamped before they are written. */
	layout: Layout,
};

/**
 *  Save a project set as a set file (E28.2): its [`SetExport`] JSON, at a
 *  path the user picked.
 */
export type SaveSetFileRequest = {
	/**  The set. */
	set: SetId,
	/**
	 *  Absolute file path. A file name with no extension gets
	 *  [`SET_FILE_EXTENSION`].
	 */
	path: string,
};

/**  A layout as it is saved in its template file. */
export type SavedLayout = {
	/**  The template file's id. */
	id: string,
	/**  The saved layout, clamped into the block ranges. */
	layout: Layout,
};

/**  A set file that was written. */
export type SavedSetFile = {
	/**  The path written, its extension added when it had none. */
	path: string,
	/**  The number of fonts in it. */
	fonts: number,
};

/**  Start a scan. Returns at once; progress arrives as `Event::ScanProgress`. */
export type ScanRequest = {
	/**  One source, or every source when absent. */
	source?: SourceId | null,
};

/**  A search. An empty query with filters lists everything that passes them. */
export type SearchRequest = {
	/**
	 *  Free text over family, style, PostScript name, foundry, designer, tags
	 *  and file name; typo-tolerant; style words ("bold italic") narrow styles.
	 */
	query?: string,
	/**  Filters. */
	filters?: Filters,
	/**
	 *  A smart-collection rule a face must pass as well, as a smart
	 *  collection applies it (E14.1: the rule editor's live count of a rule
	 *  not saved yet).
	 */
	rule?: RuleGroup | null,
	/**  Window over the family groups. */
	page?: Page,
};

/**  Search results grouped by family. */
export type SearchResponse = {
	/**  Family groups in this page. */
	families: FamilyHit[],
	/**  Family groups in all pages. */
	total: number,
	/**  The result count of every filter value. */
	counts?: FilterCounts | null,
};

/**  One tag of a [`SelectionTags`]. */
export type SelectionTag = {
	/**  The tag. */
	tag: TagId,
	/**
	 *  How many of the selection's faces carry it: all of them, or some
	 *  (a mixed state).
	 */
	faceCount: number,
	/**  True when every face of the selection carries it. */
	all: boolean,
};

/**  The tags the faces of a selection carry (E13.4). */
export type SelectionTags = {
	/**
	 *  Every face the selection names, each once: the faces first, then the
	 *  faces of each family.
	 */
	faces: FaceId[],
	/**  Every tag at least one of those faces carries, A to Z. */
	tags: SelectionTag[],
};

/**  The fonts a selection or a drag names (E13.4): faces and whole families. */
export type SelectionTagsRequest = {
	/**  The faces. */
	faces: FaceId[],
	/**  Whole families: every face of each, as the library lists it. */
	families?: FamilyId[],
};

/**  Turns a catalog on or off. Turning it off keeps its cache. */
export type SetCatalogEnabledRequest = {
	/**  The catalog. */
	id: CatalogId,
	/**  On or off. */
	enabled: boolean,
};

/**
 *  One font of an exported set, referenced by content so a teammate's copy
 *  at another path still matches.
 */
export type SetEntry = {
	/**  Family name. */
	family: string,
	/**  Style name. */
	style: string,
	/**  blake3 hash of the file, hex. */
	hash: string,
};

/**  A project set as portable JSON (no files). */
export type SetExport = {
	/**  Set name. */
	name: string,
	/**  Its fonts. */
	fonts: SetEntry[],
};

/**  A project set: fonts activated together. */
export type SetId = number;

/**  Pause or resume a source. */
export type SetSourcePausedRequest = {
	/**  The source. */
	source: SourceId,
	/**  Paused (hidden) or not. */
	paused: boolean,
};

/**
 *  The user's settings. Missing keys take their defaults.
 * 
 *  The TypeScript type marks every field optional because of the defaults;
 *  a response always carries all of them.
 */
export type Settings = {
	/**  What the Activate button does. */
	activationMode?: ActivationMode,
	/**  What activation does when a face clashes with another font. */
	onConflict?: ConflictPolicy,
	/**
	 *  Activate again, at start, the faces that were session-active when the
	 *  app last ran (off by default: a session activation ends with the app).
	 */
	reactivateOnLaunch?: boolean,
	/**  Light, dark or the OS appearance. */
	theme?: Theme,
	/**  Comfortable or compact lists. */
	density?: Density,
	/**  The largest size of the preview cache, in megabytes (64–16384). */
	cacheLimitMb?: number,
	/**
	 *  Minutes between automatic rescans of the sources; 0 turns them off
	 *  (at most 1440, one day).
	 */
	rescanIntervalMinutes?: number,
	/**
	 *  Closing the main window keeps the app running in the tray (the menu
	 *  bar on macOS), so session fonts stay active; off, closing the window
	 *  quits. On by default.
	 */
	keepInTray?: boolean,
	/**
	 *  Whether the app starts, in the tray, when the user logs in. Read from
	 *  the OS's login entry on every request, never stored in `config.json`;
	 *  `None` when this system does not offer the option (then the switch
	 *  is hidden). Off until the user turns it on.
	 */
	startAtLogin?: boolean | null,
	/**
	 *  Check for a new version when the app starts. Off unless the user
	 *  turns it on (rule 7: no network call without a user action); where
	 *  the app does not update itself the switch is hidden.
	 */
	checkUpdatesAutomatically?: boolean,
	/**
	 *  The language of the UI, the native menus and the tray; `System` by
	 *  default.
	 */
	language?: Language,
};

/**  Change some settings; absent fields keep their value. */
export type SettingsUpdate = {
	/**  What the Activate button does. */
	activationMode?: ActivationMode | null,
	/**  What activation does when a face clashes with another font. */
	onConflict?: ConflictPolicy | null,
	/**  Activate the last session's faces again at start. */
	reactivateOnLaunch?: boolean | null,
	/**  Light, dark or the OS appearance. */
	theme?: Theme | null,
	/**  Comfortable or compact lists. */
	density?: Density | null,
	/**  The largest size of the preview cache, in megabytes. */
	cacheLimitMb?: number | null,
	/**  Minutes between automatic rescans; 0 turns them off. */
	rescanIntervalMinutes?: number | null,
	/**  Keep running in the tray when the main window is closed. */
	keepInTray?: boolean | null,
	/**
	 *  Register (true) or remove (false) the login entry that starts the app
	 *  in the tray. Refused where the settings report `start_at_login: None`.
	 */
	startAtLogin?: boolean | null,
	/**  Check for a new version when the app starts. */
	checkUpdatesAutomatically?: boolean | null,
	/**  The language of the UI. */
	language?: Language | null,
};

/**  The shortlist for a brief. */
export type Shortlist = {
	/**  Best first. */
	candidates: Candidate[],
};

/**
 *  A field this machine and another machine that syncs the same folder set
 *  to different values (E28.1). The index keeps this machine's value until
 *  the user resolves it.
 */
export type SidecarConflict = {
	/**  Pass to `resolve_sidecar_conflict`. */
	id: SidecarConflictId,
	/**  The face; for a family field, the family's first face. */
	face: FaceId,
	/**  The face's family. */
	family: string,
	/**  Which field. */
	field: SidecarField,
	/**  This machine's value, in words ("4 stars", "a favorite"). */
	mine: string,
	/**  The other machine's value, in words. */
	theirs: string,
	/**  The sidecar file the other value came from. */
	sidecarPath: string,
};

/**  A sidecar value another machine set that differs from this one's. */
export type SidecarConflictId = number;

/**  The field of a sidecar conflict (E28.1). */
export type SidecarField = 
/**  The face is a favorite. */
"favorite" | 
/**  The face's rating. */
"rating" | 
/**  The face's notes. */
"notes" | 
/**  The family's notes. */
"familyNotes" | 
/**  The family's declared license. */
"familyLicense";

/**  A similar face and why. */
export type SimilarFace = {
	/**  The face. */
	face: FaceSummary,
	/**  0.0–1.0; higher is closer. */
	score: number | null,
	/**  Plain-word reasons ("matching x-height"). */
	reasons: string[],
};

/**  Faces that look like this one. */
export type SimilarRequest = {
	/**  The face to compare against. */
	face: FaceId,
	/**  Results to return. */
	limit: number,
};

/**  The metric auto size makes equal across faces (E16.2). */
export type SizeBasis = 
/**  The height of the lowercase `x`. */
"xHeight" | 
/**  The height of the capital `H`. */
"capHeight";

/**
 *  How much one face's preview size is scaled so that its x-height (or cap
 *  height) matches every other face's at the same toolbar size.
 */
export type SizeFactor = {
	/**  The face. */
	face: FaceId,
	/**
	 *  The factor to multiply the preview size by; `1` for a face with no
	 *  usable metric.
	 */
	factor: number | null,
};

/**  The auto size factors of some faces, for one basis (E16.2). */
export type SizeFactorRequest = {
	/**  The faces, usually the ones on screen. */
	faces: FaceId[],
	/**  The metric to make equal. */
	basis: SizeBasis,
};

/**  Upright, italic or oblique. */
export type Slant = 
/**  Upright. */
"upright" | 
/**  Italic. */
"italic" | 
/**  Oblique (slanted roman). */
"oblique";

/**  A source of fonts. */
export type Source = {
	/**  Id. */
	id: SourceId,
	/**  Absolute folder path. */
	path: string,
	/**  What kind of source. */
	kind: SourceKind,
	/**  Hidden from the library without being removed. */
	paused: boolean,
	/**  Faces indexed from it. */
	faceCount: number,
};

/**  A watched folder, the system fonts, or the library folder. */
export type SourceId = number;

/**  Where a source's fonts come from. */
export type SourceKind = 
/**  A folder the user chose; indexed in place. */
"watched" | 
/**  The OS font folders; read-only, never deactivated by the app. */
"system" | 
/**  The user-chosen folder that "Copy to library folder" imports into. */
"libraryFolder";

/**  The file format of a specimen (E21.1). */
export type SpecimenFormat = 
/**
 *  One self-contained HTML page: the faces are embedded, nothing is
 *  loaded from anywhere else.
 */
"html" | 
/**
 *  The same page printed by the app's webview to a paginated A4 PDF
 *  (E21.2); `Unsupported` without the app running (the CLI's direct link).
 */
"pdf";

/**  Write a specimen of one family to a file the user picked. */
export type SpecimenRequest = {
	/**  The family. */
	family: FamilyId,
	/**  The file format. */
	format: SpecimenFormat,
	/**  The file to write, as the user picked it. */
	outPath: string,
};

/**  What the specimen export wrote. */
export type SpecimenResponse = {
	/**  The file written, absolute path. */
	path: string,
};

/**  One style on a family's weight line. */
export type StyleMark = {
	/**  `OS/2.usWeightClass` (100–1000). */
	weight: number,
	/**  Italic or oblique. */
	italic: boolean,
};

/**  Which characters to keep when subsetting. */
export type Subset = 
/**  Named presets (`latin`, `latin-ext`, `cyrillic`, `greek`, `vietnamese`). */
{ kind: "presets"; 
/**  Preset names. */
names: string[] } | 
/**  CSS `unicode-range` values (`U+0000-00FF`). */
{ kind: "unicode"; 
/**  Ranges. */
ranges: string[] } | 
/**  Every character of a sample text. */
{ kind: "text"; 
/**  The text. */
text: string };

/**  Characters a font must cover. */
export type Supports = 
/**  Every listed language preset (AND), by code (`sr-Cyrl`, `pl`). */
{ kind: "languages"; 
/**  Preset codes from `list_languages`. */
codes: string[] } | 
/**  Every character of a pasted text. */
{ kind: "text"; 
/**  The text. */
text: string };

/**  A tag. */
export type Tag = {
	/**  Id. */
	id: TagId,
	/**  Name. */
	name: string,
	/**  Faces carrying it. */
	faceCount: number,
};

/**  Attach tags to faces; tags that do not exist yet are created. */
export type TagFacesRequest = {
	/**  The faces. */
	faces: FaceId[],
	/**  Tag names. */
	tags: string[],
	/**  Whole families (E13.4): every face of each, as the library lists it. */
	families?: FamilyId[],
};

/**  A free-form tag. */
export type TagId = number;

/**  What to act on. */
export type Target = 
/**  These faces. */
{ kind: "faces"; 
/**  Face ids. */
faces: FaceId[] } | 
/**  Every face of a family. */
{ kind: "family"; 
/**  Family id. */
family: FamilyId } | 
/**  Every face in a collection. */
{ kind: "collection"; 
/**  Collection id. */
collection: CollectionId } | 
/**  Every face in a project set. */
{ kind: "set"; 
/**  Set id. */
set: SetId };

/**  One block of text in a layout. */
export type TextBlock = {
	/**  The text; paragraphs are separated by a line break. */
	text: string,
	/**  Font size in points, 8–600. */
	sizePt: number | null,
	/**  Line height as a multiple of the size, 0.1–3.0. */
	lineHeight: number | null,
	/**  Letter spacing in thousandths of an em, −200–1000. */
	tracking: number | null,
	/**  Space after each paragraph in points, 0–600. */
	paragraphSpacingPt: number | null,
	/**  Indent of each paragraph's first line in em, 0–20. */
	firstLineIndentEm: number | null,
	/**  Columns the text flows into, 1–3. */
	columns: number,
	/**  Alignment. */
	align: BlockAlign,
	/**  Wrap or clip. */
	overflow: BlockOverflow,
};

/**  The colors of the app. */
export type Theme = 
/**  Follow the OS appearance. */
"system" | 
/**  Always light. */
"light" | 
/**  Always dark. */
"dark";

/**  One copy of a [`Resolution`]. */
export type TrashMove = {
	/**  The copy's path in the library. */
	path: string,
	/**  What happened to it. */
	status: TrashMoveStatus,
	/**  Why it was skipped or failed, in one sentence. */
	message: string | null,
};

/**  What happened, or would happen, to one copy. */
export type TrashMoveStatus = 
/**  Dry run: it would move to the trash. */
"planned" | 
/**  It is in the trash. */
"trashed" | 
/**  Undo put it back. */
"restored" | 
/**  It was not moved and stays where it is (`message` says why). */
"skipped" | 
/**  The move or the undo failed (`message` says why). */
"failed";

/**  Detach tags from faces. */
export type UntagFacesRequest = {
	/**  The faces. */
	faces: FaceId[],
	/**  The tags. */
	tags: TagId[],
};

/**  What a check for updates found. */
export type UpdateCheck = {
	/**  The version running now. */
	currentVersion: string,
	/**  The newer release, or `None` when this is the latest. */
	update?: AvailableUpdate | null,
};

/**
 *  Replace the rule of a smart collection (E14.1). The rule is checked as
 *  `create_collection` checks it.
 */
export type UpdateCollectionRulesRequest = {
	/**  The smart collection; a manual one is `InvalidRequest`. */
	collection: CollectionId,
	/**  The new rule. */
	ruleGroup: RuleGroup,
};

/**  How far an update moves the app, by semantic version. */
export type UpdateKind = 
/**  Fixes only (1.2.3 → 1.2.4). */
"patch" | 
/**  New features, nothing removed (1.2.3 → 1.3.0). */
"minor" | 
/**
 *  May change how the app works (1.2.3 → 2.0.0). Installed only after a
 *  second confirmation. Before 1.0, a new minor version (0.3 → 0.4) is a
 *  major step too: semver gives 0.x no compatibility promise.
 */
"major";

/**  Whether this copy of the app updates itself. */
export type UpdateSupport = {
	/**
	 *  The app offers "Check for updates"; false where something else
	 *  installs its updates (Flatpak, a package manager).
	 */
	offered: boolean,
	/**
	 *  Why not, one sentence for Settings → About → Platform notes; `None`
	 *  when offered.
	 */
	reason?: string | null,
};

/**  Change user metadata on faces; absent fields are left as they are. */
export type UserMetaUpdate = {
	/**  The faces. */
	faces: FaceId[],
	/**  Favorite or not. */
	favorite?: boolean | null,
	/**  1–5 stars; 0 clears the rating. */
	rating?: number | null,
	/**  Notes; an empty string clears them. */
	notes?: string | null,
};

/**
 *  What `GET /v1/version` answers: enough for a client to decide whether it
 *  can talk to this app before it holds a token.
 */
export type VersionInfo = {
	/**  The app version (semver). */
	appVersion: string,
	/**  The API contract this build serves. */
	apiVersion: ApiVersion,
	/**  The fields on their way out, oldest first. */
	deprecations: Deprecation[],
};

/**
 *  An instance of a variable face, pinned as a style of its own. The font
 *  file is not changed: activating it activates the face.
 */
export type VirtualStyle = {
	/**  Id. */
	id: VirtualStyleId,
	/**  The variable face it is an instance of. */
	face: FaceId,
	/**  Style name. */
	name: string,
	/**  A coordinate for every axis of the face, in the font's axis order. */
	coordinates: AxisValue[],
	/**  The manual collection that holds it, if a collection does. */
	collection?: CollectionId | null,
	/**  The project set that holds it, if a set does. */
	set?: SetId | null,
};

/**  An instance of a variable font pinned as a virtual style. */
export type VirtualStyleId = number;

/**
 *  The virtual styles of one manual collection or one project set: exactly
 *  one of `collection` and `set`.
 */
export type VirtualStylesRequest = {
	/**  The collection. */
	collection?: CollectionId | null,
	/**  The set. */
	set?: SetId | null,
};

/**  A web font format. */
export type WebFormat = 
/**  WOFF 2. */
"woff2" | 
/**  WOFF 1. */
"woff";

/**
 *  Whether a face may be used on the web, decided from its embedding
 *  permission, recognized open license and declared license type (E15.3).
 */
export type WebUse = {
	/**  The face is OK for web. */
	ok: boolean,
	/**  Why, in plain words ("Open license (OFL)"). */
	reason: string,
};

/**  An inclusive weight range (100–1000). */
export type WeightRange = {
	/**  Lowest weight. */
	min: number,
	/**  Highest weight. */
	max: number,
};

/**  An inclusive OS/2 width-class range (1 ultra-condensed – 9 ultra-expanded). */
export type WidthRange = {
	/**  Narrowest width class. */
	min: number,
	/**  Widest width class. */
	max: number,
};

export const API_VERSION: ApiVersion = { major: 0, minor: 23, patch: 0 };
